// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C{value: 1 ether}(); }

    // fuzzed parameters: actor address and a guess hash
    function testFuzz_property(address actor, bytes32 guessHash) public {
        // admissible domain: actor should not be zero address and not the test contract
        vm.assume(actor != address(0));
        vm.assume(actor != address(this));

        // fund the actor so it can send 1 ether
        vm.deal(actor, 2 ether);

        // actor calls lockInGuess with exactly 1 ether
        vm.prank(actor);
        c.lockInGuess{value: 1 ether}(guessHash);

        // Immediately after lockInGuess returns, attempt to call settle from the same actor
        // In the correct contract, lockInGuess stores block.number + 1, so settle should revert
        // because require(block.number > storedBlock) will be false in the same block.
        // In the mutant which stored block.number, settle could proceed (not revert) in the same block
        // (or at least its behavior can differ). We observe this by performing the call and
        // noting whether it succeeds (does not revert). We then assert that the correct contract
        // always causes settle to revert (ok == false). The mutant will allow ok == true for some inputs.

        bool ok;
        vm.prank(actor);
        try c.settle() {
            ok = true;
        } catch {
            ok = false;
        }

        // Single assertion: for all admissible inputs the reference contract makes this call revert (ok == false)
        assertTrue(ok == false);
    }
}

