pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C{value: 1 ether}(); }

    // Fuzz parameters: an actor address and an arbitrary guess hash.
    function testFuzz_property(address actor, bytes32 guessHash) public {
        // keep actor as a non-zero address (widened admissible domain)
        vm.assume(actor != address(0));

        // Fund the actor so they can send 1 ether
        vm.deal(actor, 2 ether);

        // Act as the actor and call lockInGuess with exactly 1 ether
        vm.prank(actor);
        // capture the block number at which the call happens
        uint256 callBlock = block.number;
        bool ok;
        try c.lockInGuess{value: 1 ether}(guessHash) {
            ok = true;
        } catch {
            ok = false;
        }
        // If the call failed, the reference contract still satisfies the property vacuously
        // so we only assert the property when the call succeeded.
        if (ok) {
            // The reference contract stores guesses[actor].block as callBlock + 1.
            // We cannot read a private mapping, but we can detect the difference by
            // observing whether settle() can be called successfully in the same block
            // (i.e. whether the stored block <= current block). The reference ensures
            // stored block > callBlock, so immediately calling settle() in the same
            // block must not be allowed to succeed (it must not pay out); the mutant
            // that stores callBlock may allow settle() to target that block and
            // therefore may change address(c).balance when settle is invoked.

            // Query contract balance before calling settle
            uint256 balBefore = address(c).balance;

            // Try to call settle in the same block as lockInGuess
            vm.prank(actor);
            bool settledOk;
            try c.settle() {
                settledOk = true;
            } catch {
                settledOk = false;
            }

            uint256 balAfter = address(c).balance;

            // General property (single assert): For the correct contract, after a successful
            // lockInGuess invoked in this block, an immediate settle() in the same block
            // cannot transfer funds out (address(c).balance must remain the same).
            // The mutant that stored block.number can make settle succeed immediately and
            // reduce the contract balance for some inputs; thus this assertion will fail
            // on that mutant for at least some fuzzed inputs.
            assertTrue(balAfter == balBefore);
        }
    }
}

