pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C{value: 1 ether}(); }

    // Fuzz parameters: caller address and a guess hash. We let the fuzzer pick both.
    function testFuzz_property(address caller, bytes32 guessHash) public {
        // admissible domain: caller must be non-zero and not the test contract itself
        vm.assume(caller != address(0));
        vm.assume(caller != address(this));

        // Give the caller 1 ether and have them call lockInGuess with exactly 1 ether.
        vm.deal(caller, 1 ether);
        vm.prank(caller);
        // perform lockInGuess in the current block
        c.lockInGuess{value: 1 ether}(guessHash);

        // Attempt to call settle immediately in the same block from the same caller using try/catch
        // If the reference contract stored block.number + 1, calling settle in the same block must not pay out.
        // We observe the effect by checking contract balance: it should NOT decrease in the reference when settle is called immediately.
        uint256 beforeBal = address(c).balance;
        bool ok;
        try c.settle() {
            ok = true;
        } catch {
            ok = false;
        }
        uint256 afterBal = address(c).balance;

        // GENERAL ASSERTION: In the correct contract, calling settle immediately after lockInGuess in the same block
        // cannot transfer the 2 ether payout (contract balance must be unchanged or settle reverted). Therefore either
        // settle reverted or succeeded but did not reduce contract balance. This will be violated by the mutant for some inputs
        // (mutant stores block.number and can allow immediate settlement when blockhash for that block is non-zero and guess matches).
        assertTrue(ok == false || afterBal == beforeBal);
    }
}

