pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C{value: 1 ether}(); }

    // Fuzz the caller address and the guess hash. For the property we need any caller
    // who calls lockInGuess with exactly 1 ether: in the correct contract the stored
    // block for that caller will be strictly in the future (block.number+1) and thus
    // settle cannot succeed in the same block. The mutant storing block.number may
    // allow settle in the same block. We detect this by calling lockInGuess and
    // immediately attempting settle in the same block; in the reference settle will
    // never send funds in the same block (so address(c).balance unchanged), while the
    // mutant can cause address(c).balance to decrease for some fuzzed inputs.
    function testFuzz_property(address caller, bytes32 guessHash) public {
        // keep caller non-zero and not the contract itself to avoid degenerate cases
        vm.assume(caller != address(0));
        vm.assume(caller != address(this));

        // Fund the caller so it can send 1 ether
        vm.deal(caller, 1 ether);

        // Make the call as the caller sending exactly 1 ether to lockInGuess
        vm.prank(caller);
        c.lockInGuess{value: 1 ether}(guessHash);

        // Immediately attempt to settle in the same block (same tx context).
        // If the contract incorrectly stored block.number, settle could pay out now
        // (if guess matches future blockhash behavior), reducing c's balance.
        uint256 balBefore = address(c).balance;

        // Try to call settle and ignore any revert; we only observe balance change.
        try c.settle() {
            // no-op
        } catch {
            // no-op
        }

        uint256 balAfter = address(c).balance;

        // GENERAL ASSERTION: In the correct contract, a same-block settle cannot succeed
        // and therefore c's balance must be unchanged immediately after calling settle.
        // This single assertTrue must hold for all admissible inputs on the reference,
        // and the mutant (storing block.number) will allow balAfter < balBefore for some inputs.
        assertTrue(balAfter == balBefore);
    }
}

