pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C{value: 1 ether}(); }

    // fuzz the caller and the guess bytes32; these determine msg.sender and the stored block
    function testFuzz_property(address actor, bytes32 guessHash) public {
        vm.assume(actor != address(0));
        // fund the actor so it can send 1 ether
        vm.deal(actor, 2 ether);

        // actor calls lockInGuess with exactly 1 ether
        vm.startPrank(actor);
        c.lockInGuess{value: 1 ether}(guessHash);
        vm.stopPrank();

        // Immediately calling settle in same block should either revert or not depending,
        // but the universal property we assert is about behavior after advancing exactly one block:
        // For the correct contract, advancing one block (roll +1) makes settle succeed (not revert)
        // and transfer back 2 ether iff the guess matches blockhash; however whether transfer happens
        // depends on guess equality. We therefore only check that the settle call does NOT revert
        // after advancing exactly one block for the correct contract. The mutant that stored block+2
        // will still require two blocks to pass and thus settle will revert after only one block for some inputs.

        // advance by one block
        vm.roll(block.number + 1);

        bool ok;
        try c.settle() {
            ok = true;
        } catch {
            ok = false;
        }

        // The correct contract guarantees that, after advancing exactly one block from lockInGuess,
        // settle will be callable (not revert) for the recorded block number = originalBlock+1.
        // The mutant that stores +2 will cause settle to still revert in those cases. Assert that settle
        // does not revert (this holds for the reference for all inputs and fails on the mutant for some).
        assertTrue(ok);
    }
}

