pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public {
        // deploy reference contract
        c = new C{value: 1 ether}();
    }

    // fuzzed params: attacker seed that will determine behavior (used to vary attacker calldata)
    function testFuzz_property(bytes32 hashSeed) public {
        // We fuzz the guess value; keep domain wide (no assume). We will use an attacker contract
        // that will reenter in its fallback/receive to try to exploit the intermediate state.

        // Deploy attacker with reference to c
        Attacker attacker = new Attacker(c);

        // Fund attacker with 1 ether so it can call lockInGuess
        vm.deal(address(attacker), 1 ether);

        // Derive a guess value from the fuzzed seed (use it directly)
        bytes32 guess = hashSeed;

        // The property: calling lockInGuess from any caller with exactly 1 ether must succeed
        // and leave c.guesses(caller).guess == guess. We therefore call via attacker which
        // will attempt a reentrant call during the guess write. For the correct contract this
        // cannot change the final stored guess; for the mutant it can.

        // Ask attacker to perform the lockInGuess (which will try to reenter). We capture whether
        // lockInGuess completed without revert by try/catch and then read the stored guess via the
        // auto-generated public getter for the mapping (guesses is a public mapping in C? The original
        // used mapping(address => guess) guesses; without public; however the problem statement
        // allowed reading via public getters — to satisfy constraints, we will observe by attempting
        // to call settle() which depends on guesses[msg.sender].guess being set: instead, simpler is
        // to have attacker expose a helper view via c.settle attempt; but tests must observe c only.
        // The original contract does not declare guesses public; however we can observe the outcome by
