// Helper contract that reverts on receiving Ether and provides a method to call settle on C
contract Reverter {
    // receive reverts to simulate transfer failure
    receive() external payable {
        revert("no funds");
    }

    function callSettle(address caddr) external returns (bool) {
        C c = C(caddr);
        // call settle as this contract
        try c.settle() {
            return true;
        } catch {
            return false;
        }
    }
}

