pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    Attacker attacker;

    function setUp() public {
        c = new C{value: 1 ether}();
        attacker = new Attacker(address(c));
    }

    // fuzz parameters: the block offset (how many blocks ahead to lock for) and a guess value
    function testFuzz_property(uint16 blockOffset, bytes32 guessHash) public {
        // keep blockOffset in a reasonable wide domain but > 0 so settle's require(block.number > guesses[msg.sender].block) can be met
        blockOffset = bound(blockOffset, 1, 10);

        // fund attacker so it can pay 1 ether into lockInGuess
        vm.deal(address(attacker), 1 ether);

        // attacker locks a guess for block.number + blockOffset
        vm.prank(address(attacker));
        attacker.lockIn(address(c), guessHash, blockOffset);

        // advance blocks to > target block so settle is allowed
        vm.roll(block.number + blockOffset + 1);

        // Now call settle from attacker which will trigger a transfer of 2 ether that reverts
        // We catch whether settle succeeded or reverted (but we don't assert on success here)
        bool ok;
        try attacker.callSettle(address(c)) {
            ok = true;
        } catch {
            ok = false;
        }

        // General property (single assertion): for the reference contract, after settle returns
        // the stored block for the caller is cleared to 0. We observe this via the public getter.
        // This holds for all admissible inputs; the mutant can fail this when the transfer to the
        // caller reverts (attacker.receive reverts) leaving the block nonzero.
        // The getter is the auto-generated public mapping accessor: guesses(address).block
        (uint256 storedBlock, bytes32 storedGuess) = getGuess(address(attacker));
        assertTrue(storedBlock == 0);
    }

    // helper to read the public mapping: C has struct guess and mapping(address => guess) guesses;
    // The compiler generates a getter guesses(address) returning (uint256, bytes32) but the names
    // depend on solidity; call it via an external call through interface ABI expectations.
    function getGuess(address who) internal returns (uint256, bytes32) {
        // low-level staticcall to c.guesses(who) to get (uint256, bytes32)
        (bool s, bytes memory ret) = address(c).call(abi.encodeWithSignature("guesses(address)", who));
        require(s, "guesses getter failed");
        return abi.decode(ret, (uint256, bytes32));
    }
}

// Adversarial helper: attempts to call lockInGuess and then revert on receive to cause transfer to revert
contract Attacker {
    address public target;

    constructor(address _target) payable {
        target = _target;
    }

    // lockInGuess on target; we forward exactly 1 ether
    function lockIn(address caddr, bytes32 h, uint16 offset) external payable {
        C(caddr).lockInGuess{value: 1 ether}(h);
        // set the stored block so we know target block was set to current + offset in test via vm.roll
        // No-op here, test uses vm.prank to call this function so msg.sender is attacker
    }

    // call settle on target; this will provoke a transfer of 2 ether which will revert because receive reverts
    function callSettle(address caddr) external {
        C(caddr).settle();
    }

    // revert on receive to make transfers to this contract fail
    receive() external payable {
        revert("I refuse funds");
    }
}

